import React, { useEffect, useState } from 'react';
import axios from 'axios';

function MedicinesList({ addToCart }) {
  const [medicines, setMedicines] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    axios.get('http://127.0.0.1:5000/api/medicines')
      .then(res => {
        setMedicines(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error(err);
        setError("Could not connect to the backend server.");
        setLoading(false);
      });
  }, []);

  if (loading) return <div className="text-center mt-20 text-xl font-bold">Loading medicines...</div>;
  if (error) return <div className="text-center mt-20 text-xl font-bold text-red-500">{error}</div>;

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-6xl mx-auto mt-8 px-4">
      {medicines.map(med => (
        <div key={med.id} className="bg-white p-6 rounded-lg shadow-lg border border-gray-100 flex flex-col items-center">
          {/* We are hardcoding a working, professional Unsplash image here */}
          <img 
            src="https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=400&q=80" 
            alt={med.name} 
            className="w-48 h-48 object-cover mb-4 rounded-lg shadow-sm" 
          />
          <h3 className="text-xl font-bold text-gray-800">{med.name}</h3>
          <p className="text-gray-500 text-sm text-center my-2">{med.description}</p>
          <span className="text-2xl font-bold text-blue-600 my-2">${med.price}</span>
          <button 
            onClick={() => addToCart(med)}
            className="mt-auto bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 w-full transition font-bold"
          >
            Add to Cart
          </button>
        </div>
      ))}
    </div>
  );
}

export default MedicinesList;
